class TransferError(ValueError):
    """Deterministic code/path/stage only; never a partial success payload."""

    def __init__(self, code, path, stage):
        self.code = code
        self.path = path
        self.stage = stage
        self.args = (code, path, stage)


def _fail(code, path, stage):
    raise TransferError(code, path, stage)


def _same(left, right):
    if type(left) is not type(right):
        return False
    if type(left) is dict:
        if any(type(key) is not str for key in left):
            return False
        if set(left) != set(right):
            return False
        return all(_same(left[key], right[key]) for key in right)
    if type(left) is list:
        return len(left) == len(right) and all(
            _same(a, b) for a, b in zip(left, right))
    if type(left) not in (str, int, bool, float, type(None)):
        return False
    return left == right


def _copy(value):
    return json.loads(json.dumps(value))


def _length(form_id):
    if type(form_id) is not str or form_id not in ("SJ-address", "J-address", "J-obj"):
        _fail("UnsupportedTransferForm", "formId", "Policy")
    if form_id == "J-obj":
        _fail("PointerOwnerNotEstablished", "formId.J-obj.pointerOwner", "Ownership")
    return 2 if form_id == "SJ-address" else 3


def transfer_geometry(form_id, origin, target):
    """Representability only; sequential end is not an observed native next PC."""
    length = _length(form_id)
    if type(origin) is not int or not 0 <= origin <= 65535:
        _fail("OriginInvalid", "origin", "Origin")
    if type(target) is not int or not 0 <= target <= 65535:
        _fail("TargetInvalid", "target", "Target")
    end = origin + length
    if end > 65536:
        _fail("SpanOutsideProfile", "origin+length", "Span")
    delta = None
    if form_id == "SJ-address":
        if end > 65535:
            _fail("NextPCOutsideProfile", "origin+length", "NoWrap")
        delta = target - end
        if not -128 <= delta <= 127:
            _fail("Rel8OutOfRange", "target-(origin+length)", "Reach")
    return {
        "passed": True, "classification": "SyntheticTransferRepresentabilityOnly",
        "formId": form_id, "origin": origin, "length": length,
        "endExclusive": end, "nextPC": end, "target": target,
        "signedDelta": delta, "targetRepresentable": True,
        "executionBlocked": True, "runtimePermission": False, "targetBytes": 0,
        "encoderCalls": 0, "decoderCalls": 0, "CPUExecutions": 0,
        "actualROMExecutions": 0,
    }


def evaluate_exit_obligations(contract, upstream):
    """Check actual historical path/terminal/context relations before metadata."""
    if not _same(upstream, UPSTREAM):
        _fail("UpstreamIdentity", "upstreamTyped", "Upstream")
    if (type(contract) is not dict or
            any(type(key) is not str for key in contract) or
            set(contract) != set(PROFILE)):
        _fail("ContractShape", "contract", "Metadata")
    continuations = contract["continuations"]
    if (type(continuations) is not list or len(continuations) != 2 or
            any(type(row) is not dict for row in continuations) or
            any(any(type(key) is not str for key in row) for row in continuations) or
            not _same([row.get("id") for row in continuations], ["NotBelow", "Below"])):
        _fail("ContinuationInventory", "continuations", "Continuation")
    sites = upstream["sites"]
    lengths = {row["pc"]: row["length"] for row in sites}
    source_paths = upstream["pathObligations"]
    source_terminals = upstream["terminalObligations"]
    path_mapping = {}
    projected_paths = []
    for index, name in enumerate(("NotBelow", "Below")):
        row = continuations[index]
        terminal = next(item for item in source_terminals if item["branch"] == name)
        paths = [item for item in source_paths if item["terminal"] == terminal["pc"]]
        last = paths[0]["pcs"][-1]
        derived_target = last + lengths[last]
        if (not _same(row.get("originalTargetPC"), derived_target) or
                not _same(row.get("lastLogicalSiteId"), last) or
                derived_target != terminal["pc"] or
                any(path["pcs"][-1] != last for path in paths)):
            _fail("TargetIdentityMismatch", "continuations." + str(index) + ".originalTargetPC", "Continuation")
        expected_ids = [path["id"] for path in paths]
        if not _same(row.get("pathIds"), expected_ids):
            _fail("PathMappingMismatch", "continuations." + str(index) + ".pathIds", "Path")
        for path in paths:
            path_mapping[path["id"]] = name
        expected_state = {key: _copy(terminal[key]) for key in
                          ("AL", "AH", "CF", "ZF", "DD", "HC", "OtherPSW")}
        expected_state.update({
            "LRB": upstream["context"]["requiredLRB"],
            "SCB": "IncomingPSWLowThreeBits", "SSP": "IncomingSSP",
            "pointingRegisters": "RetainAllSelectedAndUnselectedBanks",
            "SF": "NoNewWriter_SFMeaningStorageNotEstablished",
        })
        if not _same(row.get("requiredFinalState"), expected_state):
            _fail("ExitStateMismatch", "continuations." + str(index) + ".requiredFinalState", "Context")
        effects = []
        for path in paths:
            effects.append({
                "pathId": path["id"], "originalInstructionCount": len(path["pcs"]),
                "historicalCoverage": path["historical"],
                "orderedReads": _copy(path["orderedReads"]),
                "orderedWrites": _copy(path["orderedWrites"]),
                "mustNotRead": _copy(path["mustNotRead"]),
            })
        if not _same(row.get("requiredPathEffects"), effects):
            _fail("PathEffectsMismatch", "continuations." + str(index) + ".requiredPathEffects", "Context")
    if not _same(contract["pathToContinuation"], path_mapping):
        _fail("PathMappingMismatch", "pathToContinuation", "Path")
    if (not _same(contract["contextNoninterference"], PROFILE["contextNoninterference"]) or
            not _same(contract["upstreamStaticObligations"], PROFILE["upstreamStaticObligations"])):
        _fail("ContextMismatch", "contextNoninterference/upstreamStaticObligations", "Context")
    if (not _same(contract["inheritedLayout"], PROFILE["inheritedLayout"]) or
            not _same(contract["terminalFindings"], PROFILE["terminalFindings"])):
        _fail("TerminalHazardMismatch", "inheritedLayout/terminalFindings", "Terminal")
    if not _same(contract, PROFILE):
        _fail("Contract", "contract.closedMetadata", "Metadata")
    for path in source_paths:
        projected_paths.append({
            "pathId": path["id"], "originalInstructionCount": len(path["pcs"]),
            "continuationId": path_mapping[path["id"]],
            "originalTargetPC": path["terminal"],
            "requiredFinalAL": _copy(path["finalAL"]), "requiredCF": path["finalCF"],
            "requiredZF": path["finalZF"], "requiredDD": path["finalDD"],
            "historicalCoverage": path["historical"],
            "orderedReadSites": [item["pc"] for item in path["orderedReads"]],
            "orderedWriterSites": [item["pc"] for item in path["orderedWrites"]],
            "writeCount": len(path["orderedWrites"]), "sameValueWrites": "RetainFreshOrdinal",
            "mustNotRead": _copy(path["mustNotRead"]),
        })
    return {
        "passed": True, "classification": "StaticExternalContinuationObligations",
        "continuations": _copy(continuations), "paths": projected_paths,
        "contextNoninterference": _copy(contract["contextNoninterference"]),
        "proofLevels": _copy(PROOF_LEVELS),
        "counts": {
            "instructionSites": len(sites),
            "supportedForms": len(set(row["formId"] for row in sites)),
            "instructionLengthSum": sum(row["length"] for row in sites),
            "newExecutableSites": 0, "historicalPath13NativeWitnesses": 0,
        },
        "executionBlocked": True, "runtimePermission": False, "targetBytes": 0,
        "codecCalls": 0, "CPUExecutions": 0, "actualROMExecutions": 0,
        "currentSourceStaticOnly": True,
    }


def check_exit_state(path_id, incoming_psw, incoming_ah, final_data018f, actual_a, actual_psw):
    """Invented scalar constraints only: remainder here extracts bit fields."""
    if type(path_id) is not str or path_id not in ("A", "B", "C", "D"):
        _fail("PathInvalid", "pathId", "Input")
    for name, value, maximum in (
            ("incoming_psw", incoming_psw, 65535), ("incoming_ah", incoming_ah, 255),
            ("final_data018f", final_data018f, 255), ("actual_a", actual_a, 65535),
            ("actual_psw", actual_psw, 65535)):
        if type(value) is not int or not 0 <= value <= maximum:
            _fail("ContextValueInvalid", name, "Input")
    below = path_id == "A"
    if below and final_data018f != 15:
        _fail("ExitRAMMismatch", "final_data018f", "Context")
    required_al = 15 if below else 240 + final_data018f % 16
    if actual_a % 256 != required_al:
        _fail("ExitALMismatch", "actual_a.AL", "Context")
    if actual_a // 256 != incoming_ah:
        _fail("ExitAHMismatch", "actual_a.AH", "Context")
    cf = 1 if below else 0
    if actual_psw // 32768 != cf:
        _fail("ExitCFMismatch", "actual_psw.CF", "Context")
    if actual_psw // 16384 % 2 != 0:
        _fail("ExitZFMismatch", "actual_psw.ZF", "Context")
    if actual_psw // 4096 % 2 != 0:
        _fail("ExitDDMismatch", "actual_psw.DD", "Context")
    hc = incoming_psw // 8192 % 2
    if actual_psw // 8192 % 2 != hc:
        _fail("ExitHCMismatch", "actual_psw.HC", "Context")
    if actual_psw % 4096 != incoming_psw % 4096:
        _fail("ExitOtherPSWMismatch", "actual_psw.OtherPSW", "Context")
    return {
        "passed": True, "classification": "InventedTerminalScalarConstraintCheck_NotRuntimeState",
        "pathId": path_id, "originalTargetPC": 21957 if below else 21910,
        "AL": required_al, "AH": incoming_ah, "CF": cf, "ZF": 0, "DD": 0, "HC": hc,
        "OtherPSW": incoming_psw % 4096, "SCB": incoming_psw % 8,
        "executionBlocked": True, "runtimePermission": False, "actualRAMReads": 0,
        "actualRAMWrites": 0, "CPUExecutions": 0, "actualROMExecutions": 0,
    }


def inspect_terminal_hypothesis(layout_request, form_id):
    """Append no instruction: inspect hypothetical footprints against fixed18."""
    length = _length(form_id)
    if (type(layout_request) is not dict or
            any(type(key) is not str for key in layout_request) or
            set(layout_request) != {"syntheticBase", "gap", "classification"}):
        _fail("RequestShape", "layoutRequest", "Input")
    if not _same(layout_request["classification"], "InventedOnlyImmutableM2beGeometry"):
        _fail("Classification", "layoutRequest.classification", "Policy")
    base, gap = layout_request["syntheticBase"], layout_request["gap"]
    if type(base) is not int or not 0 <= base <= 65535:
        _fail("OriginInvalid", "layoutRequest.syntheticBase", "Origin")
    if type(gap) is not int or gap < 0:
        _fail("GapInvalid", "layoutRequest.gap", "Input")
    assignments, ends, cursor = [], {}, base
    for block, members in BLOCKS:
        if block == "Below":
            cursor += gap
        for logical, instruction_length in members:
            end = cursor + instruction_length
            if cursor > 65535 or end > 65536:
                _fail("SpanOutsideProfile", "existingAssignments." + str(logical), "Span")
            assignments.append({"logicalSiteId": logical, "syntheticAssignedPC": cursor,
                                "length": instruction_length, "endExclusive": end})
            cursor = end
        ends[block] = cursor
    by_site = {row["logicalSiteId"]: row for row in assignments}
    delta = by_site[21951]["syntheticAssignedPC"] - by_site[21885]["endExclusive"]
    for source, target in ((21885, 21951), (21893, 21906), (21896, 21906)):
        next_coordinate = by_site[source]["endExclusive"]
        distance = by_site[target]["syntheticAssignedPC"] - next_coordinate
        if next_coordinate > 65535 or not -128 <= distance <= 127:
            _fail("OldInternalBranchOutOfRange", "existingCFG." + str(source), "ExistingCFG")
    hypotheses = []
    for name, target in (("NotBelow", 21910), ("Below", 21957)):
        origin = ends[name]
        end = origin + length
        try:
            representable = transfer_geometry(form_id, origin, target)
        except TransferError as error:
            geometry = {"feasible": False, "signedDelta": None,
                        "errorCode": error.code, "stage": error.stage}
        else:
            geometry = {"feasible": True, "signedDelta": representable["signedDelta"],
                        "errorCode": None, "stage": None}
        overlaps = [row["logicalSiteId"] for row in assignments
                    if origin < row["endExclusive"] and row["syntheticAssignedPC"] < end]
        hypotheses.append({
            "continuationId": name, "originalTargetPC": target,
            "syntheticTransferOrigin": origin, "hypotheticalLength": length,
            "hypotheticalEndExclusive": end, "representability": geometry,
            "overlapLogicalSites": overlaps,
            "terminalHazard": "PotentialFallthroughIntoSyntheticBlock"
                              if name == "NotBelow" and gap == 0 else "UnmodeledGapOrOutsideRegion",
            "originalNaturalFallthroughIdentity": origin == target,
            "hypotheticalSelfTarget": origin == target,
            "spaceOwnership": "NotEstablished_NotFreeROM",
            "nativeExitIsolation": "NotEstablished", "actualDownstreamRejoin": "NotEstablished",
            "requiresFutureReservationOrRelayout": True, "transferInserted": False,
        })
    return {
        "passed": True, "classification": "HypotheticalContinuationTransferBudget_NotExecutableLayout",
        "formId": form_id,
        "existingGeometry": {"instructionSites": len(assignments),
                            "instructionLengthSum": sum(row["length"] for row in assignments),
                            "blockLengths": {block: sum(item[1] for item in members)
                                             for block, members in BLOCKS},
                            "syntheticBase": base, "gap": gap, "JLTDelta": delta,
                            "existingLayoutNotModified": True},
        "existingAssignments": assignments, "hypotheses": hypotheses,
        "hypotheticalTransferOverhead": 2 * length, "newExecutableSites": 0,
        "executionBlocked": True, "runtimePermission": False, "targetBytes": 0,
        "CPUExecutions": 0, "actualROMExecutions": 0,
    }
